SELECT DATE_FORMAT(join_date, '%m-%d') as day, count(*) as count FROM club_member WHERE del_flag = '0' AND join_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND club_id in #{cid}
GROUP BY day ORDER BY day ASC

SELECT role_type as roleType, count(*) as count FROM club_member WHERE del_flag = '0' AND status = '0'
AND club_id in #{cid}
GROUP BY role_type

SELECT c.club_name as clubName, c.club_id as clubId, count(*) as count FROM club_member m LEFT JOIN club c ON m.club_id = c.club_id WHERE m.del_flag = '0' AND m.status = '0'
AND m.club_id in #{cid}
GROUP BY c.club_name, c.club_id ORDER BY count DESC LIMIT 10
